48	export const orderSchema = z.object({
49	  planId: z.string().min(1),
50	  osTemplateId: z.string().min(1),
51	  hostname: z
52	    .string()
53	    .min(3)
54	    .max(40)
55	    .regex(/^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i, "Hostname: letters, digits, hyphens"),
56	  // Deploy-time extra-disk upsell. Coerced + step-normalized by
57	  // normalizeExtraDiskGB before it reaches here, so this is a range guard only.
58	  extraDiskGB: z.coerce.number().int().min(0).max(EXTRA_DISK_MAX_ADD_GB).optional(),
59	  // Optional checkout promo code. Uppercased + trimmed; the discount + all
60	  // redemption guards live in orderQuote / placeOrder.
61	  couponCode: z.string().trim().max(32).optional(),
62	});
