421	/**
422	 * Place an order: validate, charge the wallet (unless a free admin grant),
423	 * create the Server + PROVISION job. Returns the new server id. Does NOT
424	 * redirect. Callers must ensure funds exist (or pass free) — this still
425	 * enforces balance and throws OrderError("Insufficient balance.") otherwise.
426	 *
427	 * `sold` overrides the recomputed price with the one the order was actually SOLD
428	 * at — the card-paid path passes the figure stamped on the Checkout session
429	 * BEFORE the card was charged, so the confirm redirect settles the price the
430	 * customer consented to instead of re-pricing against whatever promo is running
431	 * when they get back (mirrors `chargeCents` in lib/resize.ts applyResize and
432	 * lib/disk-expand.ts applyDiskExpand). The wallet path omits it and pays the
433	 * quote, which it computed moments ago in the same request. See OrderPrice.
434	 */
435	/**
436	 * Claim a checkout coupon in ITS OWN atomic transaction, throwing OrderError on
437	 * any failure so nothing partial survives. Kept separate from the order tx so a
438	 * wallet order can surface the failure before any money moves, and a card order
439	 * (already paid) can swallow it without stranding the paid provision.
440	 *
441	 * Guards, all enforced here: first-time-only (no prior paid server), the
442	 * redemption cap (atomic conditional increment), one-per-account and one-per-IP
443	 * (the two @@unique constraints on CouponRedemption).
444	 */
445	async function claimOrderCoupon(opts: {
446	  couponId: string;
447	  maxRedemptions: number | null;
448	  firstTimeOnly: boolean;
449	  userId: string;
450	  ipHash: string | null;
451	  amountCents: number;
452	}): Promise<void> {
453	  await db.$transaction(async (tx) => {
454	    // Self-heal first: a dead hold from THIS customer's own abandoned card checkout must
455	    // not stand between them and this coupon on a fresh (wallet) order — and its global
456	    // slot is handed back here too. Guarded to expired RESERVED rows (lib/coupon-redemption.ts).
457	    await releaseExpiredCouponHoldsFor(tx, opts.couponId, opts.userId, opts.ipHash);
458	    if (opts.firstTimeOnly) {
459	      const prior = await tx.server.count({ where: { userId: opts.userId, isFree: false } });
460	      if (prior > 0) throw new OrderError("This code is for first-time customers only.");
461	    }
462	    // Atomic conditional increment — the only thing between the last free slot and
463	    // an over-redemption when two orders race for it.
464	    const claim = await tx.coupon.updateMany({
465	      where:
466	        opts.maxRedemptions === null
467	          ? { id: opts.couponId, active: true }
468	          : { id: opts.couponId, active: true, timesRedeemed: { lt: opts.maxRedemptions } },
469	      data: { timesRedeemed: { increment: 1 } },
470	    });
471	    if (claim.count !== 1) throw new OrderError("That code has just been fully claimed.");
472	    try {
473	      await tx.couponRedemption.create({
474	        data: { couponId: opts.couponId, userId: opts.userId, ipHash: opts.ipHash, amountCents: opts.amountCents, context: "order" },
475	      });
476	    } catch {
477	      // Unique violation on (coupon,user) or (coupon,ipHash): already claimed by
478	      // this person. Throwing rolls back the increment above with it.
479	      throw new OrderError("You’ve already used this code.");
480	    }
481	  });
482	}
