1	// Tax/VAT + multi-currency DISPLAY helpers.
2	//
3	// Plain (non-"use server") module: exports pure helpers alongside async getters
4	// that read the `Setting` store. Safe to import from server components, server
5	// actions, the worker and (the pure parts) client components. Money is always
6	// integer cents.
7	//
8	// IMPORTANT — multi-currency here is DISPLAY ONLY. `formatMoney` swaps the symbol
9	// and code for the configured `currency` Setting; it performs NO FX conversion,
10	// so the underlying cents are unchanged. Do not use this to bill in a foreign
11	// currency. Tax helpers likewise compute a display/quote breakdown; wiring them
12	// into the actual charge path is an integration step owned by the billing flow.
13	
14	import { getSetting } from "./settings";
15	
16	// ---------------- Currency (display only) ----------------
17	
18	export type CurrencyMeta = { symbol: string; code: string };
19	
20	/** Symbol/code map for the currencies we can DISPLAY. No FX rates — display only. */
21	export const CURRENCIES: Record<string, CurrencyMeta> = {
22	  USD: { symbol: "$", code: "USD" },
23	  EUR: { symbol: "€", code: "EUR" },
24	  GBP: { symbol: "£", code: "GBP" },
25	  CAD: { symbol: "CA$", code: "CAD" },
26	  AUD: { symbol: "A$", code: "AUD" },
27	  NZD: { symbol: "NZ$", code: "NZD" },
28	  INR: { symbol: "₹", code: "INR" },
29	  JPY: { symbol: "¥", code: "JPY" },
30	  CNY: { symbol: "¥", code: "CNY" },
31	  BRL: { symbol: "R$", code: "BRL" },
32	  ZAR: { symbol: "R", code: "ZAR" },
33	  CHF: { symbol: "CHF ", code: "CHF" },
34	  SEK: { symbol: "kr ", code: "SEK" },
35	  PLN: { symbol: "zł ", code: "PLN" },
36	  MXN: { symbol: "MX$", code: "MXN" },
37	  SGD: { symbol: "S$", code: "SGD" },
38	  AED: { symbol: "د.إ ", code: "AED" },
39	};
40	
41	export const DEFAULT_CURRENCY = "USD";
42	
43	/** Resolve a currency code to its symbol/code. Unknown codes fall back to `CODE `. */
44	export function currencyMeta(code: string | undefined | null): CurrencyMeta {
45	  const key = (code ?? "").trim().toUpperCase();
46	  return CURRENCIES[key] ?? { symbol: key ? `${key} ` : "$", code: key || DEFAULT_CURRENCY };
47	}
48	
49	/**
50	 * Format integer cents for DISPLAY in the given currency (default USD). Pure and
51	 * synchronous so client components can use it. No FX conversion is performed —
52	 * the numeric value is the same regardless of currency; only the symbol changes.
53	 */
54	export function formatMoney(cents: number, currencyCode: string = DEFAULT_CURRENCY): string {
55	  const { symbol } = currencyMeta(currencyCode);
56	  const n = Number.isFinite(cents) ? cents : 0;
57	  const sign = n < 0 ? "-" : "";
58	  const value = (Math.abs(n) / 100).toFixed(2);
59	  return `${sign}${symbol}${value}`;
60	}
61	
62	/** The configured display currency code (reads the `currency` Setting). */
63	export async function currentCurrency(): Promise<string> {
64	  const raw = (await getSetting("currency")).trim().toUpperCase();
65	  return raw || DEFAULT_CURRENCY;
66	}
67	
68	// ---------------- Tax / VAT ----------------
69	
70	export type TaxBreakdown = { net: number; tax: number; total: number };
71	
72	/**
73	 * The configured tax/VAT rate as a percent number (reads the `tax_percent` Setting).
74	 *
75	 * ⚠ THIS RATE IS NOT CHARGED TO ANYONE. `applyTaxFromSettings` has exactly one call site
76	 * — the MRR reference figure on /admin/products — and no charge path passes `taxCents` to
77	 * `invoiceCreateData`, so every `Invoice` row in the system stores `taxCents: 0` and every
78	 * rendered invoice shows Tax $0.00. QA P1-11 / DOCUMENTATION.md gap 22.
79	 *
80	 * Deliberately left that way. Starting to collect tax is a legal and business decision
81	 * (registration, rate by jurisdiction, reverse charge, invoice content requirements, and
82	 * remittance) and silently switching it on because a settings field existed would be a
83	 * far more serious error than the field being inert. What was fixed instead is the lie:
84	 * Settings → Billing now states on the control itself that the rate is display-only and
85	 * must not be relied on to collect VAT/GST.
86	 *
87	 * If tax is ever genuinely charged, the wiring is `applyTax()` at each charge site plus
88	 * `taxCents` into `invoiceCreateData` — and the note in
89	 * components/admin/settings/BillingPanel.tsx must be deleted in the same commit.
90	 */
91	export async function taxRate(): Promise<number> {
92	  const n = Number(await getSetting("tax_percent"));
93	  return Number.isFinite(n) && n > 0 ? n : 0;
94	}
95	
96	/**
97	 * Split a net (pre-tax) amount in cents into { net, tax, total }. Pure — pass the
98	 * rate (e.g. from `taxRate()`); the tax is rounded to the nearest cent. A rate of
99	 * 0 yields tax 0 and total === net.
100	 */
101	export function applyTax(cents: number, ratePercent: number = 0): TaxBreakdown {
102	  const net = Math.max(0, Math.round(Number.isFinite(cents) ? cents : 0));
103	  const rate = Number.isFinite(ratePercent) && ratePercent > 0 ? ratePercent : 0;
104	  const tax = Math.round((net * rate) / 100);
105	  return { net, tax, total: net + tax };
106	}
107	
108	/** Async convenience: read the configured rate and apply it in one call. */
109	export async function applyTaxFromSettings(cents: number): Promise<TaxBreakdown> {
110	  return applyTax(cents, await taxRate());
111	}
112	
113	// ---------------- Destination-country VAT (CHARGED, Finding 1) ----------------
114	//
115	// This is the part that is genuinely BILLED. `taxRate()` above is a single global
116	// rate; a real VAT obligation is per DESTINATION country, with a B2B reverse-charge
117	// carve-out. The rates below are standard-rate VAT/GST snapshots by ISO-3166 alpha-2
118	// country. They are conservative inputs to a charge: when we do not recognise a
119	// country we fall back to the configured `tax_percent` (0 unless the operator set
120	// one), never to a guess that could overcharge.
121	
122	/** EU-27 member states — the set the reverse-charge rule applies within. */
123	export const EU_COUNTRIES = new Set([
124	  "AT", "BE", "BG", "HR", "CY", "CZ", "DK", "EE", "FI", "FR", "DE", "GR", "HU",
125	  "IE", "IT", "LV", "LT", "LU", "MT", "NL", "PL", "PT", "RO", "SK", "SI", "ES", "SE",
126	]);
127	
128	/**
129	 * Standard-rate VAT/GST by destination country (percent). EU-27 + UK. Deliberately
130	 * the STANDARD rate only: reduced/zero rates are product-specific and cloud hosting
131	 * is a standard-rated electronically-supplied service in every jurisdiction here, so
132	 * the standard rate is the correct, conservative one to charge.
133	 */
134	export const COUNTRY_VAT_RATES: Record<string, number> = {
135	  AT: 20, BE: 21, BG: 20, HR: 25, CY: 19, CZ: 21, DK: 25, EE: 22, FI: 25.5,
136	  FR: 20, DE: 19, GR: 24, HU: 27, IE: 23, IT: 22, LV: 21, LT: 21, LU: 17,
137	  MT: 18, NL: 21, PL: 23, PT: 23, RO: 19, SK: 23, SI: 22, ES: 21, SE: 25,
138	  GB: 20,
139	};
140	
141	/** Normalise a country input to an uppercase ISO-3166 alpha-2 code, or "". */
142	export function normalizeCountry(country: string | null | undefined): string {
143	  const c = (country ?? "").trim().toUpperCase();
144	  return /^[A-Z]{2}$/.test(c) ? c : "";
145	}
146	
147	/**
148	 * Loose structural validation of an EU VAT identification number: the 2-letter
149	 * country prefix must match `country`, followed by 2–12 alphanumerics. This is NOT
150	 * a VIES lookup — it is deliberately conservative in the ONLY direction that moves
151	 * money: a malformed id fails here and the caller charges the destination consumer
152	 * rate rather than granting a 0% reverse charge it cannot stand behind.
153	 */
154	export function isValidVatIdFormat(vatId: string | null | undefined, country: string): boolean {
155	  const id = (vatId ?? "").replace(/\s+/g, "").toUpperCase();
156	  const c = normalizeCountry(country);
157	  if (!c || id.length < 4) return false;
158	  // The VAT id's own country prefix (Greece files under "EL", not "GR").
159	  const prefix = c === "GR" ? "EL" : c;
160	  return new RegExp(`^${prefix}[0-9A-Z]{2,12}$`).test(id);
161	}
162	
163	/** The seller's own country (ISO-3166 alpha-2), from the `seller_country` Setting. */
164	export async function sellerCountry(): Promise<string> {
165	  return normalizeCountry(await getSetting("seller_country"));
166	}
167	
168	export type TaxContext = {
169	  /** The rate actually applied to the net, in percent. */
170	  ratePercent: number;
171	  /** The destination country the rate was resolved for ("" when unknown). */
172	  country: string;
173	  /** True when a valid EU cross-border VAT id zero-rated this as a reverse charge. */
174	  reverseCharged: boolean;
175	};
176	
177	/**
178	 * Resolve the VAT/GST rate to CHARGE for a customer, from their billing country and
179	 * (optional) VAT id. Pure decision logic — the seller country and the global
180	 * fallback rate are passed in so this stays testable and callers resolve settings
181	 * once.
182	 *
183	 *   1. Unknown country                       → the global `tax_percent` fallback.
184	 *   2. Valid VAT id, EU country ≠ seller EU  → 0% (standard B2B reverse charge).
185	 *   3. Known country in the rate table       → that country's standard rate.
186	 *   4. Known country, no table entry         → the global `tax_percent` fallback.
187	 *
188	 * "When in doubt, charge the destination-country consumer rate" — a malformed VAT id
189	 * never reaches case 2 (isValidVatIdFormat gates it), so it lands on case 3.
190	 */
191	export function resolveCountryTaxRate(opts: {
192	  country: string | null | undefined;
193	  vatId?: string | null;
194	  sellerCountry: string;
195	  fallbackPercent: number;
196	}): TaxContext {
197	  const country = normalizeCountry(opts.country);
198	  const fallback = Number.isFinite(opts.fallbackPercent) && opts.fallbackPercent > 0 ? opts.fallbackPercent : 0;
199	  if (!country) return { ratePercent: fallback, country: "", reverseCharged: false };
200	
201	  // B2B reverse charge: a VAT-registered business in a DIFFERENT EU country pays 0%
202	  // and self-accounts for the VAT. Same-country B2B is still charged local VAT.
203	  const seller = normalizeCountry(opts.sellerCountry);
204	  if (
205	    EU_COUNTRIES.has(country) &&
206	    country !== seller &&
207	    isValidVatIdFormat(opts.vatId, country)
208	  ) {
209	    return { ratePercent: 0, country, reverseCharged: true };
210	  }
211	
212	  const table = COUNTRY_VAT_RATES[country];
213	  if (typeof table === "number") return { ratePercent: table, country, reverseCharged: false };
214	  return { ratePercent: fallback, country, reverseCharged: false };
215	}
216	
217	/**
218	 * Resolve the tax context for a specific customer (reads seller country + the global
219	 * fallback rate from Settings once). The single async entry point every charge site
220	 * uses so the rate is derived identically everywhere.
221	 */
222	export async function taxContextForUser(
223	  user: { billingCountry?: string | null; vatId?: string | null },
224	): Promise<TaxContext> {
225	  const [seller, fallback] = await Promise.all([sellerCountry(), taxRate()]);
226	  return resolveCountryTaxRate({
227	    country: user.billingCountry ?? null,
228	    vatId: user.vatId ?? null,
229	    sellerCountry: seller,
230	    fallbackPercent: fallback,
231	  });
232	}
233	
234	/** The tax in cents to ADD to a net service charge at a resolved rate. Integer cents. */
235	export function taxCentsFor(netCents: number, ctx: Pick<TaxContext, "ratePercent">): number {
236	  return applyTax(netCents, ctx.ratePercent).tax;
237	}
