1	import { db } from "@/lib/db";
2	import { getSetting, SETTINGS_DEFAULTS } from "@/lib/settings";
3	import { brandLabel } from "@/lib/stripe-cards";
4	import type { Invoice, InvoiceStatus, Prisma, User } from "@prisma/client";
5	
6	/**
7	 * Seller identity + number prefix printed on an invoice, resolved from Settings →
8	 * General/Billing. Read once per render and handed to the (synchronous) renderer.
9	 */
10	export type InvoiceBranding = {
11	  /** `invoice_prefix`, never blank — see `invoiceBranding()`. */
12	  numberPrefix: string;
13	  /** `brand_name`, never blank. */
14	  brandName: string;
15	  /** `company_legal_name` — "" means "omit the seller block". */
16	  legalName: string;
17	  /** `company_address` — "" means "omit the seller address". */
18	  address: string;
19	};
20	
21	const FALLBACK_BRANDING: InvoiceBranding = {
22	  numberPrefix: SETTINGS_DEFAULTS.invoice_prefix,
23	  brandName: SETTINGS_DEFAULTS.brand_name,
24	  legalName: "",
25	  address: "",
26	};
27	
28	/**
29	 * Read the invoice branding from Settings.
30	 *
31	 * `numberPrefix` is forced non-empty. `Invoice.number` is a bare autoincrement, so an
32	 * operator who clears the field would otherwise produce documents identified only as
33	 * "00012" — not quotable to a customer, not greppable in a mailbox, and impossible to
34	 * tell apart from a server ID or an order number in a support thread.
35	 *
36	 * `legalName`/`address` stay blank-able by design: the seller block is omitted entirely
37	 * when they are unset, rather than printing an empty "From" heading. That is why the
38	 * "shown on invoices" claim on the admin field is now true without the panel having to
39	 * demand a value it does not have.
40	 */
41	export async function invoiceBranding(): Promise<InvoiceBranding> {
42	  const [prefix, brandName, legalName, address] = await Promise.all([
43	    getSetting("invoice_prefix"),
44	    getSetting("brand_name"),
45	    getSetting("company_legal_name"),
46	    getSetting("company_address"),
47	  ]);
48	  return {
49	    numberPrefix: prefix.trim() || SETTINGS_DEFAULTS.invoice_prefix,
50	    brandName: brandName.trim() || SETTINGS_DEFAULTS.brand_name,
51	    legalName: legalName.trim(),
52	    address: address.trim(),
53	  };
54	}
55	
56	/**
57	 * The customer-facing invoice identifier: the configured prefix plus the zero-padded
58	 * autoincrement (`INV-00012`).
59	 *
60	 * One function so every surface agrees. The padding was previously duplicated as
61	 * `#${String(n).padStart(5, "0")}` at eight call sites, which is precisely why
62	 * `invoice_prefix` had no reader — there was no single place to wire it. The `#` sigil
63	 * is dropped now that a prefix is always present; keeping both would render `#INV-00012`.
64	 */
65	export function formatInvoiceNumber(
66	  number: number,
67	  prefix: string = SETTINGS_DEFAULTS.invoice_prefix,
68	): string {
69	  return `${prefix}${String(number).padStart(5, "0")}`;
70	}
71	
72	/**
73	 * Invoice line item shape stored in `Invoice.lineItems` (Json).
74	 * Amounts are integer cents. `amountCents` is authoritative; qty * unitCents
75	 * is used as a fallback when a line omits it.
76	 */
77	export type LineItem = {
78	  description: string;
79	  qty: number;
80	  unitCents: number;
81	  amountCents: number;
82	};
83	
84	export function coerceLineItems(raw: unknown): LineItem[] {
85	  if (!Array.isArray(raw)) return [];
86	  return raw
87	    .filter((x): x is Record<string, unknown> => !!x && typeof x === "object")
88	    .map((x) => {
89	      const qty = Number(x.qty ?? 1) || 0;
90	      const unitCents = Math.round(Number(x.unitCents ?? 0) || 0);
91	      const amountCents = Math.round(
92	        Number(x.amountCents ?? qty * unitCents) || 0
93	      );
94	      return {
95	        description: String(x.description ?? "Item"),
96	        qty,
97	        unitCents,
98	        amountCents,
99	      };
100	    });
101	}
102	
103	/** Compute subtotal / tax / total (all integer cents) for an invoice. */
104	export function invoiceTotals(invoice: Pick<Invoice, "lineItems" | "taxCents" | "amountCents">) {
105	  const items = coerceLineItems(invoice.lineItems);
106	  const subtotalCents = items.reduce((sum, li) => sum + li.amountCents, 0);
107	  const taxCents = invoice.taxCents ?? 0;
108	  // `amountCents` is the stored authoritative total; fall back to computed.
109	  const totalCents = invoice.amountCents ?? subtotalCents + taxCents;
110	  return { items, subtotalCents, taxCents, totalCents };
111	}
112	
113	const STATUS_LABEL: Record<InvoiceStatus, string> = {
114	  OPEN: "Open",
115	  PAID: "Paid",
116	  VOID: "Void",
117	  REFUNDED: "Refunded",
118	};
119	
120	export function invoiceStatusLabel(status: InvoiceStatus): string {
121	  return STATUS_LABEL[status] ?? status;
122	}
123	
124	/**
125	 * Human-readable payment method / status line for an invoice.
126	 *
127	 * PAID/REFUNDED → "Paid with Visa •••• 4242 on Aug 3, 2026", using the stamped
128	 * card snapshot (`paidBrand`/`paidLast4`). For invoices issued before the snapshot
129	 * existed those are null, so we FALL BACK to the user's current card fields —
130	 * historical invoices still read correctly. If no card is known at all we show a
131	 * plain "Paid …". OPEN → "Awaiting payment"; VOID → "Void".
132	 */
133	export function invoicePaymentMethod(
134	  invoice: Pick<Invoice, "status" | "paidAt" | "paidBrand" | "paidLast4">,
135	  fallbackCard?: { cardBrand: string | null; cardLast4: string | null } | null,
136	): string {
137	  if (invoice.status === "OPEN") return "Awaiting payment";
138	  if (invoice.status === "VOID") return "Void";
139	
140	  const brand = invoice.paidBrand ?? fallbackCard?.cardBrand ?? null;
141	  const last4 = invoice.paidLast4 ?? fallbackCard?.cardLast4 ?? null;
142	  const verb = invoice.status === "REFUNDED" ? "Refunded" : "Paid";
143	  const when = invoice.paidAt ? ` on ${fmtDate(invoice.paidAt)}` : "";
144	  if (last4) return `${verb} with ${brandLabel(brand)} •••• ${last4}${when}`;
145	  return `${verb}${when}`;
146	}
147	
148	export type InvoiceInput = {
149	  userId: string;
150	  description: string;
151	  lineItems: LineItem[];
152	  taxCents?: number;
153	  /** VAT/GST rate (percent) applied to the net — recorded on the invoice (Finding 1). */
154	  taxRatePercent?: number;
155	  /** Destination country the tax was charged for (ISO-3166 alpha-2). */
156	  taxCountry?: string | null;
157	  status?: InvoiceStatus;
158	  period?: { start?: Date | null; end?: Date | null };
159	  /**
160	   * Card snapshot to stamp when this invoice is created already PAID (renewals,
161	   * auto-charges). Ignored for non-PAID invoices. Null-safe: a user with no saved
162	   * card leaves these null and the UI falls back to their current card fields.
163	   */
164	  paidBrand?: string | null;
165	  paidLast4?: string | null;
166	};
167	
168	/**
169	 * Build the `data` payload for an Invoice row WITHOUT touching the database, so
170	 * a charge site can create the invoice inside its own guarded `$transaction`
171	 * (sharing the charge's idempotency guard) via `tx.invoice.create({ data })`.
172	 * The stored total (`amountCents`) is always derived from line items + tax so
173	 * callers can't desync the stamped total from the itemised breakdown.
174	 */
175	export function invoiceCreateData(opts: InvoiceInput): Prisma.InvoiceUncheckedCreateInput {
176	  const items = opts.lineItems.map((li) => ({
177	    description: String(li.description),
178	    qty: Number(li.qty) || 0,
179	    unitCents: Math.round(Number(li.unitCents) || 0),
180	    amountCents: Math.round(
181	      Number(li.amountCents ?? (Number(li.qty) || 0) * (Number(li.unitCents) || 0)) || 0
182	    ),
183	  }));
184	  const taxCents = Math.round(opts.taxCents ?? 0);
185	  const subtotalCents = items.reduce((s, li) => s + li.amountCents, 0);
186	  const amountCents = subtotalCents + taxCents;
187	  const status = opts.status ?? "OPEN";
188	
189	  return {
190	    userId: opts.userId,
191	    description: opts.description,
192	    lineItems: items,
193	    taxCents,
194	    // Record the rate + jurisdiction on any invoice that actually collected tax; a
195	    // zero-tax invoice (top-up, unknown country, reverse charge) leaves them 0/null.
196	    taxRatePercent: taxCents > 0 ? Math.round((opts.taxRatePercent ?? 0) * 1e4) / 1e4 : 0,
197	    taxCountry: taxCents > 0 ? opts.taxCountry ?? null : null,
198	    amountCents,
199	    status,
200	    paidAt: status === "PAID" ? new Date() : null,
201	    // Only stamp the paying card on invoices born PAID; an OPEN invoice has not
202	    // been charged to any card yet.
203	    paidBrand: status === "PAID" ? opts.paidBrand ?? null : null,
204	    paidLast4: status === "PAID" ? opts.paidLast4 ?? null : null,
205	    periodStart: opts.period?.start ?? null,
206	    periodEnd: opts.period?.end ?? null,
207	  };
208	}
