211	 * Create an Invoice row directly. The total (`amountCents`) is derived from the
212	 * line items plus tax so callers can't accidentally desync the stamped total
213	 * from the itemised breakdown.
214	 */
215	export async function createInvoice(opts: InvoiceInput): Promise<Invoice> {
216	  return db.invoice.create({ data: invoiceCreateData(opts) });
