1	// Customer-facing view of the dunning ladder.
2	//
3	// WHY THIS FILE EXISTS
4	// `worker/billing.ts` owns the dunning POLICY, and every constant that shapes it
5	// (`retryDayFor`, `CARD_SUSPEND_DAY`, `DUNNING_EXHAUSTED`, `SUSPEND_SLIP_CAP_DAYS`,
6	// `suspendDueAt`) is module-private there. The portal cannot import them: that file
7	// pulls in the provisioning worker's whole world — Proxmox, nodemailer, the job
8	// queue — and none of it belongs in a page bundle.
9	//
10	// So the DAY ARITHMETIC is duplicated here, deliberately, and each constant is
11	// named exactly as the worker names it so a change to the schedule is greppable.
12	// This is the same trade `lib/actions-settings.ts` already makes for
13	// MIN_TERMINATE_DAYS, and it is guarded the same way: `test/payment-method-ui.test.ts`
14	// reads worker/billing.ts and fails the moment the two disagree.
15	//
16	// DUNNING_RETRY_ATTEMPTS itself is IMPORTED rather than copied. It is the one number
17	// the dunning emails subtract from ("we'll try 2 more times"), and a second copy of
18	// it is precisely how that promise starts outliving the retries that back it.
19	//
20	// Plain server module. Everything below is pure arithmetic on the columns the worker
21	// writes, so a server component can compute the view once and hand plain data to a
22	// client component — no clock or database access hides in here.
23	
24	import { DUNNING_RETRY_ATTEMPTS } from "./mailer";
25	
26	export { DUNNING_RETRY_ATTEMPTS };
27	
28	const DAY = 86_400_000;
29	
30	/** Mirrors `const retryDayFor = (retry: number) => 2 * retry - 1;` in worker/billing.ts. */
31	export const retryDayFor = (retry: number) => 2 * retry - 1;
32	/** Mirrors `const CARD_SUSPEND_DAY = LAST_RETRY_DAY + 1;` — one clear day after the final notice. */
33	const SUSPEND_DAYS_AFTER_LAST_RETRY = 1;
34	/** Mirrors `const SUSPEND_SLIP_CAP_DAYS = 4;` in worker/billing.ts. */
35	export const SUSPEND_SLIP_CAP_DAYS = 4;
36	/**
37	 * Mirrors `const CARD_EXPIRY_WARN_DAYS = 30;` in worker/billing.ts — how far ahead
38	 * the worker emails about a card that is about to expire. The portal flags the card
39	 * on exactly the same day the email goes out, so the two never disagree about
40	 * whether a card counts as "expiring soon".
41	 */
42	export const CARD_EXPIRY_WARN_DAYS = 30;
43	
44	/** Days past expiry on which the worker retries the saved card. */
45	export const RETRY_DAYS: number[] = Array.from({ length: DUNNING_RETRY_ATTEMPTS }, (_, i) =>
46	  retryDayFor(i + 1),
47	);
48	/** Days past expiry of the LAST automatic retry. */
49	export const LAST_RETRY_DAY = retryDayFor(DUNNING_RETRY_ATTEMPTS);
50	/** Days past expiry when a card customer's server pauses, if nothing has been paid. */
51	export const CARD_SUSPEND_DAY = LAST_RETRY_DAY + SUSPEND_DAYS_AFTER_LAST_RETRY;
52	/**
53	 * `Server.dunningStage` once every automatic attempt is spent: the attempt made on
54	 * expiry day itself, plus one per retry. Mirrors
55	 * `const DUNNING_EXHAUSTED = DUNNING_RETRY_ATTEMPTS + 1;`.
56	 */
57	export const DUNNING_EXHAUSTED = DUNNING_RETRY_ATTEMPTS + 1;
58	
59	/** The columns `worker/billing.ts` reads to decide what happens to an overdue server. */
60	export type DunningInput = {
61	  expiresAt: Date | null;
62	  dunningStage: number;
63	  dunningNextAt: Date | null;
64	};
65	
66	export type DunningView = {
67	  /** Whether this account can actually be auto-charged — changes the whole ladder. */
68	  hasCard: boolean;
69	  /** True once at least one automatic card attempt has FAILED for this period. */
70	  inDunning: boolean;
71	  /** Automatic attempts already spent (the expiry-day attempt plus any retries). */
72	  attemptsMade: number;
73	  /**
74	   * Every automatic attempt the ladder will ever make. Zero without a card: the
75	   * worker makes no attempt at all, so promising four would be a lie.
76	   */
77	  attemptsTotal: number;
78	  /** Attempts still to come. Zero means the final notice has already been sent. */
79	  attemptsLeft: number;
80	  /** True once every automatic attempt is spent — suspension is the next event. */
81	  exhausted: boolean;
82	  /** When the worker will next try the card. Null when nothing is scheduled. */
83	  nextAttemptAt: Date | null;
84	  /**
85	   * When the server pauses if nothing is paid — the same expression `suspendDueAt`
86	   * evaluates, including the promise-keeping slip and its cap. Null when the admin
87	   * kill switch has auto-suspend off, in which case nothing pauses on a timer.
88	   */
89	  suspendAt: Date | null;
90	  /** Whole days since the term ran out. Negative before expiry. */
91	  daysPastExpiry: number;
92	};
93	
94	/**
95	 * Days past expiry of the plain calendar deadline, before any late-sequence slip.
96	 * Mirrors `calendarSuspendDay` in worker/billing.ts.
97	 */
98	function calendarSuspendDay(graceDays: number, hasCard: boolean): number {
99	  return hasCard ? Math.max(graceDays, CARD_SUSPEND_DAY) : graceDays;
100	}
101	
102	/**
103	 * Mirrors `suspendDueAt` in worker/billing.ts, including the rule that a suspension
104	 * never lands before a retry date we have already promised the customer by email —
105	 * and that the slip that buys is capped, so a Stripe outage cannot defer it forever.
106	 */
107	function suspendDueAt(
108	  server: DunningInput,
109	  hasCard: boolean,
110	  cfg: { graceDays: number; autoSuspend: boolean },
111	): Date | null {
112	  if (!cfg.autoSuspend || !server.expiresAt) return null;
113	  const days = calendarSuspendDay(cfg.graceDays, hasCard);
114	  const at = new Date(server.expiresAt.getTime() + days * DAY);
115	  if (!hasCard || !server.dunningNextAt || server.dunningNextAt <= at) return at;
116	  const cap = new Date(server.expiresAt.getTime() + (days + SUSPEND_SLIP_CAP_DAYS) * DAY);
117	  return server.dunningNextAt < cap ? server.dunningNextAt : cap;
118	}
119	
120	/**
121	 * Turn the raw dunning columns into something a customer can be told without
122	 * over-promising.
123	 *
124	 * Two states the UI must never conflate, which is why they are separate fields:
125	 * a customer with NO card is not "0 of 4 attempts made" — the worker will never
126	 * attempt anything for them, and they go to grace and then suspension on the
127	 * shorter clock. `attemptsTotal` is 0 in that case rather than 4.
128	 */
129	export function dunningView(
130	  server: DunningInput,
131	  opts: { hasCard: boolean; graceDays: number; autoSuspend: boolean; now: Date },
132	): DunningView {
133	  const { hasCard, graceDays, autoSuspend, now } = opts;
134	  const attemptsMade = hasCard ? Math.min(Math.max(0, server.dunningStage), DUNNING_EXHAUSTED) : 0;
135	  const attemptsTotal = hasCard ? DUNNING_EXHAUSTED : 0;
136	  return {
137	    hasCard,
138	    inDunning: server.dunningStage > 0,
139	    attemptsMade,
140	    attemptsTotal,
141	    attemptsLeft: Math.max(0, attemptsTotal - attemptsMade),
142	    exhausted: hasCard && server.dunningStage >= DUNNING_EXHAUSTED,
143	    nextAttemptAt: hasCard ? server.dunningNextAt : null,
144	    suspendAt: suspendDueAt(server, hasCard, { graceDays, autoSuspend }),
145	    daysPastExpiry: server.expiresAt
146	      ? Math.floor((now.getTime() - server.expiresAt.getTime()) / DAY)
147	      : 0,
148	  };
149	}
