{!isLast ? (
  // Gated on the CURRENT step, not just Install. Leaving Access with an
  // empty hostname used to be allowed, and the customer only discovered
  // it four steps later on a Deploy button that would not light up.
  <button
    key="wizard-continue"
    type="button"
    className="btn-primary"
    disabled={!!primaryBlocker}
    aria-describedby={primaryBlocker ? "wizard-blocker" : undefined}
    onClick={() => setStep((s) => s + 1)}
  >
    Continue →
  </button>
) : (
  <button
    key="wizard-deploy"
    type="submit"
    className="btn-primary px-6"
    disabled={pending || !canDeploy}
    aria-describedby={deployBlocker ? "wizard-blocker" : undefined}
    onClick={() => { submittedRef.current = true; }}
  >
